import json
import urllib.request
import urllib.parse
from typing import Any, Type, TypeVar, Union
from .models.protocols import AHReportError, AHHTTPMethod
from .models.results import AHLogResult, AHAlertResult, AHAdoptionResult, AHCommonResult

T = TypeVar('T')


class AHReportService:
    def __init__(self, timeout: int = 30):
        self.timeout = timeout

    def send(self, report, result_type: Type[T]) -> Union[T, AHReportError]:
        try:
            report.validate()
            url = report.base_url + report.endpoint
            params = report.parameters()
            return self._perform_request(url, report.http_method, params, result_type)
        except AHReportError as e:
            return e
        except Exception as e:
            return AHReportError.invalid_request(str(e))

    def _perform_request(self, url: str, method: AHHTTPMethod, params: dict,
                         result_type: Type[T]) -> T:
        try:
            headers = {'Content-Type': 'application/json'}

            if method == AHHTTPMethod.GET and params:
                query = urllib.parse.urlencode({k: v for k, v in params.items() if v is not None})
                url = f'{url}?{query}'
                data = None
            else:
                data = json.dumps(params).encode('utf-8')

            req = urllib.request.Request(url, data=data, headers=headers, method=method.value)
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                body = resp.read().decode('utf-8')
                response_data = json.loads(body)
                return self._parse_response(response_data, result_type)

        except AHReportError:
            raise
        except Exception as e:
            raise AHReportError.network_failure(e)

    def _parse_response(self, data: dict, result_type: Type[T]) -> Any:
        if not isinstance(data, dict):
            raise AHReportError.invalid_response('Invalid JSON format')

        if result_type is AHLogResult:
            return AHLogResult(
                result=data.get('result'),
                message=data.get('message'),
                api_response=data.get('api_response'),
            )
        if result_type is AHAlertResult:
            return AHAlertResult(
                code=data.get('code'),
                message=data.get('message'),
                data=data.get('data'),
            )
        if result_type in (AHAdoptionResult, AHCommonResult):
            return result_type(
                returncode=data.get('returncode'),
                message=data.get('message'),
                result=data.get('result'),
            )
        return result_type(**data)

    def send_post_to_route(self, route: str, data: dict):
        try:
            body = json.dumps(data).encode('utf-8')
            req = urllib.request.Request(
                route, data=body,
                headers={'Content-Type': 'application/json'},
                method='POST'
            )
            with urllib.request.urlopen(req, timeout=self.timeout):
                pass
        except Exception as e:
            print(f'send_post_to_route error: {e}')
